    // MARK: - Preset Dispatch

    static func grid(for preset: AvatarPreset) -> [String] {
        switch preset {
        case .knightV1: return KnightV1Grid
        case .knightV2: return KnightV2Grid
        case .knightV3: return KnightV3Grid
        case .knightV4: return KnightV4Grid
        case .guardianV1: return GuardianV1Grid
        case .guardianV2: return GuardianV2Grid
        case .guardianV3: return GuardianV3Grid
        case .guardianV4: return GuardianV4Grid
        case .healerV1: return HealerV1Grid
        case .healerV2: return HealerV2Grid
        case .healerV3: return HealerV3Grid
        case .healerV4: return HealerV4Grid
        case .mageV1: return MageV1Grid
        case .mageV2: return MageV2Grid
        case .mageV3: return MageV3Grid
        case .mageV4: return MageV4Grid
        case .rogueV1: return RogueV1Grid
        case .rogueV2: return RogueV2Grid
        case .rogueV3: return RogueV3Grid
        case .rogueV4: return RogueV4Grid
        }
    }

    static func palette(for preset: AvatarPreset) -> [Character: Color] {
        switch preset {
        case .knightV1: return KnightV1Palette
        case .knightV2: return KnightV2Palette
        case .knightV3: return KnightV3Palette
        case .knightV4: return KnightV4Palette
        case .guardianV1: return GuardianV1Palette
        case .guardianV2: return GuardianV2Palette
        case .guardianV3: return GuardianV3Palette
        case .guardianV4: return GuardianV4Palette
        case .healerV1: return HealerV1Palette
        case .healerV2: return HealerV2Palette
        case .healerV3: return HealerV3Palette
        case .healerV4: return HealerV4Palette
        case .mageV1: return MageV1Palette
        case .mageV2: return MageV2Palette
        case .mageV3: return MageV3Palette
        case .mageV4: return MageV4Palette
        case .rogueV1: return RogueV1Palette
        case .rogueV2: return RogueV2Palette
        case .rogueV3: return RogueV3Palette
        case .rogueV4: return RogueV4Palette
        }
    }
